Object.assign(SNIP,{"h16khuon": "int l = 0;\nfor (int r = 0; r < n; r++) {\n    them(a[r]);                      // đưa a[r] vào cửa sổ\n    while (/* cửa sổ [l, r] vi phạm điều kiện */) {\n        bot(a[l]);                   // bỏ a[l] ra khỏi cửa sổ\n        l++;\n    }\n    // [l, r] là đoạn tốt dài nhất kết thúc tại r\n    // đoạn dài nhất: max(r - l + 1); đếm số đoạn tốt: cộng thêm (r - l + 1)\n}"});PRESET_NOTES["l16"]={"Ví dụ: Đếm đoạn có tổng ≤ S (số không âm)": "Tại mỗi r, [l, r] là đoạn dài nhất kết thúc ở r có tổng ≤ 5, nên có r − l + 1 đoạn tốt kết thúc ở r. Kết quả 8.", "Ví dụ: Đoạn dài nhất có không quá k giá trị khác nhau": "cnt đếm số lần mỗi giá trị trong cửa sổ, khac là số giá trị khác nhau. Đoạn dài nhất có ≤ 2 giá trị: 1 3 3 3 hoặc 3 3 3 2 (độ dài 4).", "Ví dụ: Cửa sổ độ dài k có tổng lớn nhất": "Cửa sổ độ dài cố định: mỗi bước thêm một phần tử bên phải, bỏ một phần tử bên trái. Kết quả 6 (−5 + 9 + 2)."};EX_HINTS["l16"]=[["Số không âm nên đoạn tổng ≤ S thì mọi đoạn con cũng ≤ S: dùng được hai con trỏ.", "Tại mỗi r, cộng r − l + 1 vào kết quả.", "Số đoạn tới khoảng 5·10⁹: long long."], ["Giữ cnt[x] = số lần x xuất hiện trong cửa sổ và khac = số giá trị có cnt > 0.", "Thêm a[r]: nếu cnt từ 0 lên 1 thì khac tăng. Bỏ a[l]: nếu cnt về 0 thì khac giảm."], ["Code mẫu tính lại tổng từng cửa sổ: O(n · k).", "Trượt cửa sổ: thêm a[r], bỏ a[r − k].", "Số có thể âm hết: best bắt đầu từ LLONG_MIN."]];
