const PR16=[{label:"Ví dụ: Đếm đoạn có tổng ≤ S (số không âm)",input:"5 5\n2 1 3 2 4",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"DEMDOAN.INP\", \"r\")) {\n        freopen(\"DEMDOAN.INP\", \"r\", stdin);\n        freopen(\"DEMDOAN.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long S;\n    cin >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    long long tong = 0, dem = 0;\n    int l = 0;\n    for (int r = 0; r < n; r++) {\n        tong += a[r];\n        while (tong > S) {\n            tong -= a[l];\n            l++;\n        }\n        dem += r - l + 1;\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["l","r"],range:["l","r"]},{type:"vars",names:["tong","dem"]}]},{label:"Ví dụ: Đoạn dài nhất có không quá k giá trị khác nhau",input:"7 2\n1 2 1 3 3 3 2",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"KHACNHAU.INP\", \"r\")) {\n        freopen(\"KHACNHAU.INP\", \"r\", stdin);\n        freopen(\"KHACNHAU.OUT\", \"w\", stdout);\n    }\n    int n, k;\n    cin >> n >> k;\n    vector<int> a(n);\n    for (auto& x : a) cin >> x;\n    vector<int> cnt(100001, 0);\n    int khac = 0, best = 0, l = 0;\n    for (int r = 0; r < n; r++) {\n        if (cnt[a[r]] == 0) khac++;\n        cnt[a[r]]++;\n        while (khac > k) {\n            cnt[a[l]]--;\n            if (cnt[a[l]] == 0) khac--;\n            l++;\n        }\n        best = max(best, r - l + 1);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["l","r"],range:["l","r"]},{type:"vars",names:["khac","best"]}]},{label:"Ví dụ: Cửa sổ độ dài k có tổng lớn nhất",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, -1, 4, 1, -5, 9, 2};\n    int n = a.size(), k = 3;\n    long long s = 0, best = LLONG_MIN;\n    for (int r = 0; r < n; r++) {\n        s += a[r];\n        if (r >= k) s -= a[r - k];          // bỏ phần tử vừa ra khỏi cửa sổ\n        if (r >= k - 1) best = max(best, s);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["r"]},{type:"vars",names:["s","best"]}]}];
